// Generate a random byte buffer and reinterpret into a UTF-16 code unit sequence.
// We do not assume validity; underlying function defines behavior for ill-formed data.
std::string bytes = FUZZ_PARAM_STR();
// Keep inputs modest for performance
if (bytes.size() > 1024) bytes.resize(1024);
std::u16string u16;
// Construct u16 by packing bytes into char16_t; if odd length, pad last high byte with 0
u16.reserve((bytes.size() + 1) / 2);
for (size_t i = 0; i < bytes.size(); i += 2) {
    unsigned char b0 = static_cast<unsigned char>(bytes[i]);
    unsigned char b1 = (i + 1 < bytes.size()) ? static_cast<unsigned char>(bytes[i + 1]) : 0u;
    char16_t cu = static_cast<char16_t>((static_cast<uint16_t>(b1) << 8) | static_cast<uint16_t>(b0));
    u16.push_back(cu);
}
std::u16string_view sv(u16);
try {
    // Invoke target: allocate and return a new UTF-8 string
    std::string out = utf8::utf16to8(sv);
    // Touch the result to avoid optimizing away and exercise internal paths
    if (!out.empty()) {
        volatile unsigned char sink = static_cast<unsigned char>(out[0]);
        (void)sink;
    }
} catch (const std::exception&) {
    // Underlying implementation may throw on ill-formed input; convert to fuzzer bail
    FUZZ_BAIL();
} catch (...) {
    FUZZ_BAIL();
}
